for line in rows.strip().splitlines():
 name,mode,regions,drugs,summary,symptoms,non,source=line.split('|')
 id=re.sub(r'[^a-z0-9]+','-',name.lower()).strip('-')
 if id in original:continue
 data['conditions'].append({'id':id,'name':name,'mode':mode,'regionIds':regions.split(','),'summary':summary,'commonSymptoms':symptoms.split(';'),'drugIds':drugs.split(',') if drugs else [],'nonDrugTreatments':non.split(';'),'_review':'pending','source':'https://medlineplus.gov/'+source})
for c in data['conditions']:
 if c['id']=='type-1-diabetes' and 'pancreas' not in c['regionIds']:c['regionIds'].append('pancreas')
p.write_text(json.dumps(data,indent=2)+'\n')
regions=json.load(open('data/regions.json'))['regions'];report=[]
for r in regions:
 if r['parentId'] or r['id'] in ['skin','systemic']:
  cs=[c for c in data['conditions'] if r['id'] in c['regionIds']];report.append({'region':r['name'],'regionId':r['id'],'added':sum(c['id'] not in original for c in cs),'total':len(cs)})
json.dump({'before':len(original),'after':len(data['conditions']),'added':len(data['conditions'])-len(original),'byRegion':report},open('data/model-reports/content-coverage.json','w'),indent=2)
print('TOTAL',len(data['conditions']),'ADDED',len(data['conditions'])-len(original));print('Underfilled:',[r for r in report if r['total']<2])
